const html: Record<string, string> = {"pill":"<a class=\"gx gx-pill\" href=\"/request-demo\"><i class=\"gx-live\" aria-hidden=\"true\"></i> Early access open · pilots now →</a>","top":"<section class=\"gx gx-marquee\" aria-label=\"Built for\"><p class=\"gx-eyebrow\">Built for the people who deliver on the sponsorship deck</p><div class=\"gx-marquee-mask\"><ul class=\"gx-track\"><li>Partnership managers</li><li>Event organizers</li><li>Festivals</li><li>Conferences</li><li>Sports clubs</li><li>Leagues</li><li>Venues</li><li>Trade shows</li><li>Cultural institutions</li><li>Agencies</li><li>Brand partners</li><li>Activation teams</li><li aria-hidden=\"true\">Partnership managers</li><li aria-hidden=\"true\">Event organizers</li><li aria-hidden=\"true\">Festivals</li><li aria-hidden=\"true\">Conferences</li><li aria-hidden=\"true\">Sports clubs</li><li aria-hidden=\"true\">Leagues</li><li aria-hidden=\"true\">Venues</li><li aria-hidden=\"true\">Trade shows</li><li aria-hidden=\"true\">Cultural institutions</li><li aria-hidden=\"true\">Agencies</li><li aria-hidden=\"true\">Brand partners</li><li aria-hidden=\"true\">Activation teams</li></ul></div></section>\n<section id=\"problem\" class=\"gx gx-section\"><div class=\"gx-wrap\"><div><p class=\"gx-eyebrow\">The problem</p><h2 class=\"gx-h2\">Sponsors want proof. Organizers have a folder of photos and a spreadsheet.</h2><p class=\"gx-intro\">Commitments are buried in agreements, fulfilment is tracked by memory, and post-event reports mix recorded results with guesses. Renewals depend on evidence nobody gathered at the time.</p></div><div class=\"gx-grid gx-g3\"><figure class=\"gx-card gx-fig gx-reveal gx-lift gx-spot gx-d0\"><div class=\"gx-stat-v\"><b class=\"gx-b\" data-count=\"76\" data-dec=\"0\">76</b><span>%</span></div><figcaption><p>of US B2C marketing leaders who invested in sports sponsorships in 2024 say they struggle to calculate the ROI.</p><a class=\"gx-src\" href=\"https://www.forrester.com/blogs/sports-sponsorships-surge-despite-fuzzy-roi\" target=\"_blank\" rel=\"noopener noreferrer\">Source: Forrester, Q4 2024 B2C Marketing CMO Pulse Survey ↗</a></figcaption></figure><figure class=\"gx-card gx-fig gx-reveal gx-lift gx-spot gx-d2\"><div class=\"gx-stat-v\"><small>€</small><b class=\"gx-b\" data-count=\"30.9\" data-dec=\"1\">30.9</b><span>bn</span></div><figcaption><p>spent on sponsorship in Europe — a record, and every euro comes with commitments to prove.</p><a class=\"gx-src\" href=\"https://www.insideworldfootball.com/2024/03/15/europes-sponsorship-market-hits-e30-9bn-record/\" target=\"_blank\" rel=\"noopener noreferrer\">Source: European Sponsorship Association, via Inside World Football ↗</a></figcaption></figure><figure class=\"gx-card gx-fig gx-reveal gx-lift gx-spot gx-d4\"><div class=\"gx-stat-v\"><b class=\"gx-b\" data-count=\"1\" data-dec=\"0\">1</b><span>%</span></div><figcaption><p>of sponsorship budgets is spent on measuring the return, on average.</p><a class=\"gx-src\" href=\"https://www.ticketmanager.com/?p=26351\" target=\"_blank\" rel=\"noopener noreferrer\">Source: WFA &amp; Lumency, Evolution of Sponsorship, via TicketManager ↗</a></figcaption></figure></div><p class=\"gx-small\">Published figures from third-party sources, linked above. They describe the sponsorship market, not SponsorMap results. SponsorMap never generates reach or engagement figures.</p></div></section>\n<section id=\"solution\" class=\"gx gx-section gx-tint\"><div class=\"gx-wrap\"><div><p class=\"gx-eyebrow\">What we solve</p><h2 class=\"gx-h2\">From a folder of photos to a sponsor-ready report you can stand behind.</h2></div><div class=\"gx-grid gx-g2\"><div class=\"gx-card gx-reveal\"><p class=\"gx-eyebrow gx-eyebrow-muted\">Today</p><ul class=\"gx-list\"><li><span class=\"gx-ic no\" aria-label=\"No\">✕</span><span class=\"gx-muted\">Commitments live in PDFs nobody re-reads before the event.</span></li><li><span class=\"gx-ic no\" aria-label=\"No\">✕</span><span class=\"gx-muted\">Fulfilment is tracked in a spreadsheet and someone’s memory.</span></li><li><span class=\"gx-ic no\" aria-label=\"No\">✕</span><span class=\"gx-muted\">Evidence arrives in WhatsApp groups after the event.</span></li><li><span class=\"gx-ic no\" aria-label=\"No\">✕</span><span class=\"gx-muted\">Reports blend recorded numbers with estimates.</span></li><li><span class=\"gx-ic no\" aria-label=\"No\">✕</span><span class=\"gx-muted\">Renewal conversations start without the facts.</span></li></ul></div><div class=\"gx-card gx-with gx-reveal gx-spot gx-d2\"><p class=\"gx-eyebrow\">With SponsorMap</p><ul class=\"gx-list\"><li><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span><span>Every commitment extracted from the agreement and reviewed.</span></li><li><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span><span>Fulfilment tasks assigned with owners and due dates.</span></li><li><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span><span>Evidence collected against each commitment, then verified.</span></li><li><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span><span>Reports that separate recorded metrics from labelled estimates.</span></li><li><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span><span>A clear record to open the renewal conversation.</span></li></ul></div></div></div></section>","mid":"<section id=\"compare\" class=\"gx gx-section\"><div class=\"gx-wrap\"><div><p class=\"gx-eyebrow\">Why SponsorMap</p><h2 class=\"gx-h2\">How it compares with the way sponsorships are run today</h2><p class=\"gx-intro\">SponsorMap sits between the signed agreement and the sponsor report — it keeps every promise tracked and evidenced.</p></div><div class=\"gx-table-wrap gx-reveal\"><table class=\"gx-table\"><thead><tr><th><span class=\"gx-sr\">Capability</span></th><th>Spreadsheets &amp; folders</th><th>Project tools</th><th>CRM</th><th class=\"gx-us\">SponsorMap</th></tr></thead><tbody><tr><th scope=\"row\">Commitments extracted from agreements</th><td><span class=\"gx-cell\"><span class=\"gx-ic no\" aria-label=\"No\">✕</span> Retyped</span></td><td><span class=\"gx-cell\"><span class=\"gx-ic no\" aria-label=\"No\">✕</span> —</span></td><td><span class=\"gx-cell\"><span class=\"gx-ic part\" aria-label=\"Partly\">–</span> Deal fields</span></td><td class=\"gx-us\"><span class=\"gx-cell\"><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span> Reviewed, clause by clause</span></td></tr><tr><th scope=\"row\">Fulfilment tracked per commitment</th><td><span class=\"gx-cell\"><span class=\"gx-ic part\" aria-label=\"Partly\">–</span> Tabs</span></td><td><span class=\"gx-cell\"><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span> Tasks</span></td><td><span class=\"gx-cell\"><span class=\"gx-ic no\" aria-label=\"No\">✕</span> —</span></td><td class=\"gx-us\"><span class=\"gx-cell\"><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span> Linked to the clause</span></td></tr><tr><th scope=\"row\">Evidence attached and verified</th><td><span class=\"gx-cell\"><span class=\"gx-ic part\" aria-label=\"Partly\">–</span> Photo folders</span></td><td><span class=\"gx-cell\"><span class=\"gx-ic part\" aria-label=\"Partly\">–</span> Attachments</span></td><td><span class=\"gx-cell\"><span class=\"gx-ic no\" aria-label=\"No\">✕</span> —</span></td><td class=\"gx-us\"><span class=\"gx-cell\"><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span> Reviewed before reporting</span></td></tr><tr><th scope=\"row\">Recorded vs estimated metrics</th><td><span class=\"gx-cell\"><span class=\"gx-ic no\" aria-label=\"No\">✕</span> Mixed</span></td><td><span class=\"gx-cell\"><span class=\"gx-ic no\" aria-label=\"No\">✕</span> —</span></td><td><span class=\"gx-cell\"><span class=\"gx-ic no\" aria-label=\"No\">✕</span> —</span></td><td class=\"gx-us\"><span class=\"gx-cell\"><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span> Always separated</span></td></tr><tr><th scope=\"row\">Sponsor-ready reports</th><td><span class=\"gx-cell\"><span class=\"gx-ic part\" aria-label=\"Partly\">–</span> Slides by hand</span></td><td><span class=\"gx-cell\"><span class=\"gx-ic no\" aria-label=\"No\">✕</span> —</span></td><td><span class=\"gx-cell\"><span class=\"gx-ic no\" aria-label=\"No\">✕</span> —</span></td><td class=\"gx-us\"><span class=\"gx-cell\"><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span> Generated from the record</span></td></tr><tr><th scope=\"row\">Invents reach or impressions</th><td><span class=\"gx-cell\"><span class=\"gx-ic part\" aria-label=\"Partly\">–</span> Sometimes</span></td><td><span class=\"gx-cell\"><span class=\"gx-ic no\" aria-label=\"No\">✕</span> —</span></td><td><span class=\"gx-cell\"><span class=\"gx-ic no\" aria-label=\"No\">✕</span> —</span></td><td class=\"gx-us\"><span class=\"gx-cell\"><span class=\"gx-ic no\" aria-label=\"No\">✕</span> By design — never</span></td></tr></tbody></table></div></div></section>\n<section id=\"ai\" class=\"gx gx-section gx-tint\"><div class=\"gx-wrap gx-split gx-even\"><div><div><p class=\"gx-eyebrow\">AI, used carefully</p><h2 class=\"gx-h2\">Extracts commitments. Never invents results.</h2><p class=\"gx-intro\">SponsorMap uses AI to read agreements and draft reports. Every metric comes from a recorded source or is labelled as an estimate with its method.</p></div><ul class=\"gx-list\"><li class=\"gx-card gx-li-card gx-reveal gx-lift gx-d0\"><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span><span>Extract commitments from a sponsorship agreement</span></li><li class=\"gx-card gx-li-card gx-reveal gx-lift gx-d1\"><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span><span>List what’s outstanding before the event</span></li><li class=\"gx-card gx-li-card gx-reveal gx-lift gx-d2\"><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span><span>Draft a sponsor report from verified evidence</span></li><li class=\"gx-card gx-li-card gx-reveal gx-lift gx-d3\"><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span><span>Cite the clause or record behind every answer</span></li><li class=\"gx-card gx-li-card gx-reveal gx-lift gx-d4\"><span class=\"gx-ic no\" aria-label=\"No\">✕</span><span>Generate reach, impressions or engagement numbers</span></li><li class=\"gx-card gx-li-card gx-reveal gx-lift gx-d5\"><span class=\"gx-ic no\" aria-label=\"No\">✕</span><span>Mark a commitment fulfilled without evidence</span></li></ul></div><div class=\"gx-card gx-chat gx-reveal gx-d2\"><div class=\"gx-chat-head\">Sponsorship assistant <span class=\"gx-badge\">Sample data</span></div><p class=\"gx-bubble-q\">What’s left to deliver for Northwind before Saturday?</p><div class=\"gx-bubble-a\">Three commitments: logo on the main-stage LED wall (clause 4.2, no evidence yet), 20 VIP passes (issued, awaiting confirmation) and a social post on day one (scheduled).<em>From the Northwind agreement and the fulfilment tracker</em></div><p class=\"gx-bubble-q\">How many people saw their logo?</p><div class=\"gx-bubble-a gx-muted\">I don’t generate reach figures. I can include recorded attendance from your ticketing data, clearly labelled, and any estimate with its method.</div><a class=\"gx-btn gx-mt\" href=\"/demo\">Try it in the live demo →</a></div></div></section>","end":"<section id=\"team\" class=\"gx gx-section gx-tint\"><div class=\"gx-wrap\"><div><p class=\"gx-eyebrow\">Team</p><h2 class=\"gx-h2\">The people building SponsorMap</h2><p class=\"gx-intro\">Founded by Temitope Afolabi (Founder/CEO) and Obinna Eze (Co-founder/CTO), and built together with the teams who will use it.</p></div><div class=\"gx-mt44\"><div class=\"gx gx-grid gx-g2 gx-mt0\"><article class=\"gx-card gx-reveal gx-lift gx-spot gx-d0\"><div class=\"gx-person\"><div class=\"gx-avatar\" aria-hidden=\"true\"><b>TA</b></div><div class=\"gx-min0\"><p class=\"gx-role\">Founder/CEO</p><h3>Temitope Afolabi</h3><p>Temitope founded SponsorMap so organizers can prove every sponsorship promise with evidence — and leads product, partners and every pilot.</p><ul class=\"gx-tags\" aria-label=\"Focus areas\"><li>Product</li><li>Organizers</li><li>Pilots</li></ul></div></div></article><article class=\"gx-card gx-reveal gx-lift gx-spot gx-d2\"><div class=\"gx-person\"><div class=\"gx-avatar\" aria-hidden=\"true\"><b>OE</b></div><div class=\"gx-min0\"><p class=\"gx-role\">Co-founder/CTO</p><h3>Obinna Eze</h3><p>Obinna co-founded SponsorMap and leads its technology — from agreement extraction and evidence review to the cloud platform behind it.</p><ul class=\"gx-tags\" aria-label=\"Focus areas\"><li>Document AI</li><li>Evidence engine</li><li>Cloud platform</li></ul></div></div></article></div></div></div></section>\n<section id=\"roadmap\" class=\"gx gx-section\"><div class=\"gx-wrap\"><div><p class=\"gx-eyebrow\">Roadmap</p><h2 class=\"gx-h2\">Where SponsorMap is going</h2><p class=\"gx-intro\">Built with early-access customers. The order below is our plan and may change based on what pilots teach us.</p></div><ol class=\"gx-grid gx-g4 gx-ol\"><li class=\"gx-card gx-reveal gx-lift gx-now gx-d0\"><div class=\"gx-stage\"><span><i class=\"gx-live\" aria-hidden=\"true\"></i>Now</span></div><h3>Live demo &amp; early access</h3><ul class=\"gx-list gx-list-sm\"><li><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span><span class=\"gx-muted\">Interactive fulfilment demo</span></li><li><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span><span class=\"gx-muted\">Dashboard overview on a fictional festival</span></li><li><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span><span class=\"gx-muted\">Recorded vs estimated reporting</span></li><li><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span><span class=\"gx-muted\">Demo requests open</span></li></ul></li><li class=\"gx-card gx-reveal gx-lift gx-d2\"><div class=\"gx-stage\"><span>Next</span></div><h3>Pilot with one event</h3><ul class=\"gx-list gx-list-sm\"><li><span class=\"gx-ic part\" aria-label=\"Partly\">–</span><span class=\"gx-muted\">Commitment extraction with Amazon Bedrock</span></li><li><span class=\"gx-ic part\" aria-label=\"Partly\">–</span><span class=\"gx-muted\">Evidence uploads to Amazon S3</span></li><li><span class=\"gx-ic part\" aria-label=\"Partly\">–</span><span class=\"gx-muted\">Sponsor report export</span></li></ul></li><li class=\"gx-card gx-reveal gx-lift gx-d3\"><div class=\"gx-stage\"><span>Then</span></div><h3>General availability</h3><ul class=\"gx-list gx-list-sm\"><li><span class=\"gx-ic part\" aria-label=\"Partly\">–</span><span class=\"gx-muted\">Multi-event portfolios</span></li><li><span class=\"gx-ic part\" aria-label=\"Partly\">–</span><span class=\"gx-muted\">SSO with roles enforced on the server</span></li><li><span class=\"gx-ic part\" aria-label=\"Partly\">–</span><span class=\"gx-muted\">Sponsor portal</span></li></ul></li><li class=\"gx-card gx-reveal gx-lift gx-d5\"><div class=\"gx-stage\"><span>Later</span></div><h3>Exploring with pilots</h3><ul class=\"gx-list gx-list-sm\"><li><span class=\"gx-ic part\" aria-label=\"Partly\">–</span><span class=\"gx-muted\">Ticketing and attendance imports</span></li><li><span class=\"gx-ic part\" aria-label=\"Partly\">–</span><span class=\"gx-muted\">Renewal briefs</span></li><li><span class=\"gx-ic part\" aria-label=\"Partly\">–</span><span class=\"gx-muted\">Inventory planning</span></li></ul></li></ol></div></section>\n<section id=\"faq\" class=\"gx gx-section\"><div class=\"gx-wrap gx-split\"><div><div><p class=\"gx-eyebrow\">FAQ</p><h2 class=\"gx-h2\">Questions organizers ask</h2></div><a class=\"gx-link\" href=\"mailto:hello@sponsormap.site\">✉ Email the founders</a></div><div class=\"gx-faq gx-reveal\"><details><summary>Does SponsorMap generate reach or impressions figures?</summary><p>No. We never generate reach, impressions or engagement figures. Reports show recorded metrics from your sources and label any estimate with its method.</p></details><details><summary>What problem does it actually solve?</summary><p>Sponsorship commitments are buried in agreements and fulfilment is tracked by memory, so reports lack evidence. SponsorMap turns agreements into tracked commitments, collects evidence against each and produces sponsor-ready reports.</p></details><details><summary>How is AI used?</summary><p>To extract commitments from agreements and draft reports from verified evidence — always citing the clause or record. Important commitments require human review.</p></details><details><summary>Can sponsors see the reports?</summary><p>Yes — reports are generated from the verified record and can be shared with each sponsor.</p></details><details><summary>How much does it cost?</summary><p>See the pricing page. Prices are illustrative and exclude taxes.</p></details><details><summary>Is it available today?</summary><p>SponsorMap is in early access and still being built. The demo runs on a fictional festival; a pilot runs on one of your events. Request a demo and a founder will reply personally.</p></details></div></div></section>","privacy":"<section class=\"gx gx-section gx-legal\"><div class=\"gx-wrap\"><p class=\"gx-eyebrow\">Review draft · operator details to be confirmed</p><h1 class=\"gx-h2\">Privacy notice</h1><h2>What this website is</h2><p>This website describes SponsorMap and includes an interactive demo that runs on sample data. No customer systems are connected.</p><h2>Demo data</h2><p>Changes you make in the demo are kept in your browser (local storage) or in the demo server’s memory and contain only sample data. Clearing site data removes them.</p><h2>Early-access requests</h2><p>When the request form is connected to a customer-relationship service (proposed: HubSpot), submitting it sends the fields you enter, your consent choices and the page address to that service so SponsorMap can reply. Product updates are sent only if you opt in. Until then, requests are kept in your browser and you are offered a pre-filled email to hello@sponsormap.site.</p><h2>Analytics and cookies</h2><p>This website includes no advertising trackers. A hosting provider may process routine request data to serve and protect the site.</p><h2>Your requests</h2><p>Contact hello@sponsormap.site with questions about information you have sent to SponsorMap, or to ask for it to be corrected or deleted.</p><p class=\"gx-small gx-mt34\">Contact: <a href=\"mailto:hello@sponsormap.site\">hello@sponsormap.site</a></p></div></section>","terms":"<section class=\"gx gx-section gx-legal\"><div class=\"gx-wrap\"><p class=\"gx-eyebrow\">Review draft · operator details to be confirmed</p><h1 class=\"gx-h2\">Terms of use</h1><h2>Demonstration only</h2><p>The demo runs on sample data. It is not a production system and must not be used for real sponsorship reporting.</p><h2>People decide</h2><p>SponsorMap organises information and flags items for review. Decisions stay with qualified people on your team.</p><h2>Pricing and availability</h2><p>Prices shown are illustrative and exclude taxes. Early-access requests do not create a subscription or any commitment.</p><h2>Use of the site</h2><p>Use the site and demo lawfully. Do not upload personal or confidential information to the demo.</p><h2>Changes</h2><p>These terms are a review draft. Operator details, governing law and service terms will be set out before launch.</p><p class=\"gx-small gx-mt34\">Contact: <a href=\"mailto:hello@sponsormap.site\">hello@sponsormap.site</a></p></div></section>"};

